var dataTable;
$(document).ready(function () {
	dataTable = $("#datatable").DataTable({		
		"ajax": {
			"url":"/nationsreportcard/snapshots/data/state_district.json"
		},
		searching: true,
		search: {RegExp: true},
		info: false, 
		lengthChange: false,
		"columns": [
			{ "data": "Jurisdiction" },
			{ "data": "Type" },
			{ "data": "Subject" },
			{ "data": "Year" },
			{ "data": "Grade4" },
			{ "data": "Grade8" },
			{ "data": "Grade12" }
		],
		"deferRender": true,	//speed boost rendering.
		"aaSorting": [ [3, "desc"], [1, "desc"], [0, "asc"] ],

		//Remember pagenation.
		stateSave: true,
		stateSaveCallback: function (settings, data) {
			localStorage.setItem("DataTables_" + settings.sInstance, JSON.stringify(data));
		},
		stateLoadCallback: function (settings) {
			var pageData = JSON.parse(localStorage.getItem("DataTables_" + settings.sInstance));
			return pageData;
		}
	}); //end of dataTable()

    //Select box events; modify if dropdowns get loaded by AJAX in the future.
	$(".toggle-slider .accessible-version").on("click",toggleAccessibleVersionPopup);
	$(".toggle-slider .accessible-version-popup").on("click",toggleAccessibleVersionPopup);
	$(".table-search .dropdown .dropdown-text").on("click",SelectTextClick);
	$(".table-search .dropdown .dropdown-text").on("focus",SelectTextFocus);
	$(".table-search .dropdown .select-checkbox").on("focusout",SelectBlur);
	$(".table-search .dropdown .dropdown-text").on("keydown",SelectKeydown);
	$(".table-search .dropdown .select-checkbox").on("keydown",SelectKeydown);
	$(".table-search .dropdown .select-checkbox input:checkbox").on("change",SelectCheckChange);
	$(".table-search .buttons:not(.remove-filters)").on("click", selectPillClick);

	loadFilters();

}); //end of $(document).ready

const const_states				= "States";
const const_urbanDistricts		= "Urban Districts";
const const_urbanDistricts_css	= "UrbanDistricts";
const const_subjects			= "Subjects";
const const_years				= "Years";
const const_sel_state			= " - Select State - ";
const const_sel_district		= " - Select District - ";
const const_sel_subject			= " - Select Subject - ";
const const_sel_year			= " - Select Year - ";
const const_sel_multi			= " - Multiple Selected - "

var eventFromKeyboard	= false;
var accessibleKeyboard	= false;
var fromButton			= false;
var dropdownLabels		= [const_sel_state, const_sel_district, const_sel_subject, const_sel_year];

/* =====================================
	Store Filters when trigger
		1. Accessible Version toggle.
		2. Apply Filers click.
		3. Checkboxes check/uncheck.
		4. Pills click.
   ===================================== */
function SaveFilters() {
	// Pills.
	var pillData = [];
	var pill = { classname: "", label: "" };
	var pillButtons = $(".table-search .pill");
	if (pillButtons.length > 0) {
		pillButtons.each(function (index, pillButton) {
			pill.classname = $(pillButton).attr("class").split(" ")[1];
			pill.label = $(pillButton).attr("name");
			pillData.push([pill.classname, pill.label]);
		});
	}

	// Accessibility Version toggle.
	var $btnToggle = $("#accessibilityToggle");
	if ($btnToggle.is(":checked")) {
		pillData.push([$btnToggle.attr("id"), true]);
	}

	// No data to store.
	if (pillData.length > 0) {
		pillData[0] == "none";
	}

	localStorage.setItem("DataTables_Filters", JSON.stringify(pillData));
}

function loadFilters() {
	var filterValues = JSON.parse(localStorage.getItem("DataTables_Filters"));

	if (filterValues == null || filterValues[0] == "none") { return; }

	// 1. Accessibility Version toggle.
	filterValues.filter(function (item) {
		if (item[0] == $("#accessibilityToggle").attr("id")) {
			accessibleKeyboard = item[1];
			return;
		}
	});
	$("#accessibilityToggle").prop("checked", accessibleKeyboard);

	// 2. 'Apply Filters' button.
	if (accessibleKeyboard) {
		$(".table-search .search-wrapper .button-apply-filters").removeClass("hide");
	}
	else {
		$(".table-search .search-wrapper .button-apply-filters").addClass("hide");
	}

	// 3. Pi

